window.STUDY_DATA = {"version": 4, "deckType": "concept", "modules": ["Analytics foundations", "Classification and preparation", "Validation and selection", "Clustering and distance", "Outliers", "Change detection", "Time series", "Regression and inference", "PCA and transformations", "Trees, probabilities, and decisions"], "cards": [{"id": "R-001", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "What is descriptive analytics?", "answer": "Summarizes observed patterns and relationships.", "explanation": "", "links": [], "objective": "what-is-descriptive-analytics"}, {"id": "R-002", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "What is predictive analytics?", "answer": "Estimates unknown or future outcomes.", "explanation": "", "links": [], "objective": "what-is-predictive-analytics"}, {"id": "R-003", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "What is prescriptive analytics?", "answer": "Chooses actions using objectives, constraints, and consequences.", "explanation": "", "links": [], "objective": "what-is-prescriptive-analytics"}, {"id": "R-004", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "What can the term model refer to?", "answer": "A method family, a predictor specification, or a fitted numerical model.", "explanation": "For example: linear regression as a method, a chosen set of predictors, or an equation with estimated coefficients.", "links": [{"label": "ISLR author companion courses", "url": "https://www.statlearning.com/online-courses"}], "objective": "what-can-the-term-model-refer-to"}, {"id": "R-005", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "What is the modeling cycle from reality to recommendations?", "answer": "Represent reality mathematically, analyze it, then interpret the result in context.", "explanation": "", "links": [], "objective": "what-is-the-modeling-cycle-from-reality-to-recommendations"}, {"id": "R-006", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "Why must model choice begin with the operational question?", "answer": "Different questions require different outputs.", "explanation": "", "links": [], "objective": "why-must-model-choice-begin-with-the-operational-question"}, {"id": "R-008", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "What is the difference between statistical inference and prediction?", "answer": "Inference examines relationships; prediction estimates new outcomes.", "explanation": "", "links": [], "objective": "what-is-the-difference-between-statistical-inference-and-prediction"}, {"id": "R-010", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "How should interpretability affect model selection?", "answer": "Balance explanation requirements against predictive performance and operational usefulness.", "explanation": "Compare usefulness, explanation requirements, and validation performance. A forest can outperform one tree without meeting a requirement for a short explainable rule.", "links": [{"label": "ISLR author companion courses", "url": "https://www.statlearning.com/online-courses"}], "objective": "how-should-interpretability-affect-model-selection"}, {"id": "R-011", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "Why can a mathematically good fit still be operationally unsuitable?", "answer": "A model can answer its mathematical question while missing the actual operational goal.", "explanation": "", "links": [], "objective": "why-can-a-mathematically-good-fit-still-be-operationally-unsuitable"}, {"id": "R-012", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "How does an outcome prediction differ from choosing an action?", "answer": "Prediction estimates an outcome; a decision also considers actions, costs, and constraints.", "explanation": "", "links": [], "objective": "how-does-an-outcome-prediction-differ-from-choosing-an-action"}, {"id": "C-001", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "objective": "unknown-present-prediction", "stem": "Must a predictive target describe the future?", "answer": "No. Prediction can estimate an unknown present response as well as a future response.", "explanation": "", "links": []}, {"id": "C-002", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "objective": "fitted-parameter-versus-setting", "stem": "How do learned parameters differ from chosen model settings?", "answer": "Parameters are fitted values such as slopes or centers; settings choose structure or tradeoffs such as k or a penalty.", "explanation": "Terminology can vary. Distinguish values estimated during fitting from settings chosen to define the procedure.", "links": [{"label": "ISLR author companion courses", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "R-013", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What do rows and columns normally represent in a data table?", "answer": "Rows: observations. Columns: attributes, predictors, and possibly the response.", "explanation": "", "links": [], "objective": "what-do-rows-and-columns-normally-represent-in-a-data-table"}, {"id": "R-014", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Which names are used for explanatory variables?", "answer": "Attributes, features, predictors, covariates, and independent variables.", "explanation": "The term independent variable is a naming convention; it does not guarantee independence or causality.", "links": [{"label": "StatQuest video catalog: nearest neighbors", "url": "https://statquest.org/video_index.html"}, {"label": "ISLR statistical-learning resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "which-names-are-used-for-explanatory-variables"}, {"id": "R-015", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "How does the response differ from a predictor?", "answer": "The response is what you estimate; predictors are the information used.", "explanation": "", "links": [], "objective": "how-does-the-response-differ-from-a-predictor"}, {"id": "R-016", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "How do quantitative and categorical data differ?", "answer": "Quantitative values measure amounts; categorical values identify groups.", "explanation": "", "links": [], "objective": "how-do-quantitative-and-categorical-data-differ"}, {"id": "R-017", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Why should numeric identifiers not automatically define quantitative distances?", "answer": "Identifier numbers name categories; their differences need not represent meaningful similarity.", "explanation": "", "links": [], "objective": "why-should-numeric-identifiers-not-automatically-define-quantitative-distances"}, {"id": "R-018", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What is a binary variable?", "answer": "A variable with two possible categories.", "explanation": "", "links": [], "objective": "what-is-a-binary-variable"}, {"id": "R-019", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "How does structured data differ from unstructured data?", "answer": "Structured data has defined fields; unstructured input needs a suitable representation.", "explanation": "", "links": [], "objective": "how-does-structured-data-differ-from-unstructured-data"}, {"id": "R-020", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What makes data a time series?", "answer": "Observations have a meaningful temporal order.", "explanation": "", "links": [], "objective": "what-makes-data-a-time-series"}, {"id": "R-021", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What is supervised learning?", "answer": "Learning from observations with known responses.", "explanation": "", "links": [], "objective": "what-is-supervised-learning"}, {"id": "R-022", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What is unsupervised learning?", "answer": "Learning patterns without known response labels.", "explanation": "", "links": [], "objective": "what-is-unsupervised-learning"}, {"id": "R-023", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What is classification?", "answer": "Predicting a category or class.", "explanation": "", "links": [], "objective": "what-is-classification"}, {"id": "R-024", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What is a linear classifier's decision function?", "answer": "f(x)=b+sum(w_j*x_j); classify using its sign or a specified threshold.", "explanation": "", "links": [], "objective": "what-is-a-linear-classifier-s-decision-function"}, {"id": "R-025", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What does a vertical classifier boundary imply in an x1-horizontal,x2-vertical plot?", "answer": "Only x1 controls that fitted threshold rule.", "explanation": "", "links": [], "objective": "what-does-a-vertical-classifier-boundary-imply-in-an-x1-horizontal-x2-vertical-plot", "diagram": "vertical"}, {"id": "R-026", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What does a horizontal classifier boundary imply in an x1-horizontal,x2-vertical plot?", "answer": "Only x2 controls that fitted threshold rule.", "explanation": "", "links": [], "objective": "what-does-a-horizontal-classifier-boundary-imply-in-an-x1-horizontal-x2-vertical-plot", "diagram": "horizontal"}, {"id": "R-027", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What is a hyperplane?", "answer": "A linear separating boundary in multiple dimensions.", "explanation": "", "links": [], "objective": "what-is-a-hyperplane"}, {"id": "R-028", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What objective distinguishes a hard-margin SVM?", "answer": "Correctly separate the training classes with the widest margin to the nearest class points.", "explanation": "The closest margin-constraining points matter. More points far inside the correct class need not change the separating geometry.", "links": [{"label": "StatQuest SVM video", "url": "https://youtu.be/efR1C6CvhmE"}, {"label": "ISLR classification resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "what-objective-distinguishes-a-hard-margin-svm"}, {"id": "R-029", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Why does the hard-margin SVM derivation use labels -1/+1?", "answer": "They let one signed condition describe both classes.", "explanation": "", "links": [], "objective": "why-does-the-hard-margin-svm-derivation-use-labels-1-1"}, {"id": "R-031", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What are support vectors in the separable SVM picture?", "answer": "The nearest training points that constrain the margin.", "explanation": "", "links": [], "objective": "what-are-support-vectors-in-the-separable-svm-picture"}, {"id": "R-032", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Why use a soft-margin classifier?", "answer": "To balance margin against fitting errors when strict separation is unsuitable.", "explanation": "", "links": [], "objective": "why-use-a-soft-margin-classifier"}, {"id": "R-035", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "How does lambda act in the stated SVM objective loss + lambda*norm(w)^2?", "answer": "Increasing lambda emphasizes the coefficient penalty rather than training fit.", "explanation": "Inspect the stated objective. Weighting the coefficient penalty favors a different tradeoff from weighting the fitting loss.", "links": [{"label": "StatQuest SVM video", "url": "https://youtu.be/efR1C6CvhmE"}, {"label": "ISLR classification resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "how-does-lambda-act-in-the-stated-svm-objective-loss-lambda-norm-w-2"}, {"id": "R-036", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Can a shared parameter symbol be interpreted the same way across different model specifications?", "answer": "Its effect depends on the model and the term it controls.", "explanation": "", "links": [], "objective": "can-a-shared-parameter-symbol-be-interpreted-the-same-way-across-different-model-specifications"}, {"id": "R-037", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "How should an SVM tradeoff setting be selected?", "answer": "Compare held-out performance under the relevant error costs; training perfection is insufficient.", "explanation": "", "links": [], "objective": "how-should-an-svm-tradeoff-setting-be-selected"}, {"id": "R-038", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "How can SVM handle unequal mistake costs?", "answer": "Change error penalties or the decision boundary to reflect unequal consequences.", "explanation": "", "links": [], "objective": "how-can-svm-handle-unequal-mistake-costs"}, {"id": "R-039", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What does a kernel SVM add?", "answer": "A more flexible, potentially nonlinear separating boundary.", "explanation": "", "links": [], "objective": "what-does-a-kernel-svm-add"}, {"id": "R-040", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Why is an SVM score not automatically a probability?", "answer": "It is a decision score, not automatically a fitted event probability.", "explanation": "A sign or threshold produces a class. An event-probability model answers a different question.", "links": [{"label": "StatQuest SVM video", "url": "https://youtu.be/efR1C6CvhmE"}, {"label": "ISLR classification resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "why-is-an-svm-score-not-automatically-a-probability"}, {"id": "R-041", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What is k-NN classification's prediction rule?", "answer": "Choose the most frequent label among the k nearest training cases.", "explanation": "", "links": [], "objective": "what-is-k-nn-classification-s-prediction-rule"}, {"id": "R-042", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Does a multiclass k-NN winner require more than half the votes?", "answer": "No. A plurality is enough.", "explanation": "", "links": [], "objective": "does-a-multiclass-k-nn-winner-require-more-than-half-the-votes"}, {"id": "R-043", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Why can odd k still produce a k-NN tie?", "answer": "Multiclass vote counts or equal distances can still tie.", "explanation": "", "links": [], "objective": "why-can-odd-k-still-produce-a-k-nn-tie"}, {"id": "R-044", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "How does increasing k generally affect neighbor predictions?", "answer": "Larger neighborhoods generally smooth local variation.", "explanation": "", "links": [], "objective": "how-does-increasing-k-generally-affect-neighbor-predictions"}, {"id": "R-045", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Why can irrelevant dimensions hurt k-NN?", "answer": "They can distort which cases appear close.", "explanation": "", "links": [], "objective": "why-can-irrelevant-dimensions-hurt-k-nn"}, {"id": "R-046", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What is min-max scaling to zero and one?", "answer": "(x-training minimum)/(training maximum-training minimum).", "explanation": "", "links": [], "objective": "what-is-min-max-scaling-to-zero-and-one"}, {"id": "R-047", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "How do you scale u in [0,1] to endpoints a and b?", "answer": "a+(b-a)*u.", "explanation": "", "links": [], "objective": "how-do-you-scale-u-in-0-1-to-endpoints-a-and-b"}, {"id": "R-048", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What is standardization?", "answer": "(x-training mean)/training standard deviation.", "explanation": "", "links": [], "objective": "what-is-standardization"}, {"id": "R-049", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "When do scaling formulas need special handling?", "answer": "When the feature's range or standard deviation is zero.", "explanation": "", "links": [], "objective": "when-do-scaling-formulas-need-special-handling"}, {"id": "R-050", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Why can future min-max scaled values exceed one or fall below zero?", "answer": "New observations can lie outside the training range.", "explanation": "", "links": [], "objective": "why-can-future-min-max-scaled-values-exceed-one-or-fall-below-zero"}, {"id": "C-003", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "objective": "knn-required-inputs", "stem": "What information does k-NN classification need?", "answer": "Labeled training cases, a feature representation and distance rule, a neighborhood size, and tie handling.", "explanation": "", "links": []}, {"id": "C-004", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "objective": "svm-required-inputs", "stem": "What information and choices define an SVM classification problem?", "answer": "Predictor features, known class labels, an appropriate representation, and the specified margin/error tradeoff.", "explanation": "Kernel and penalty choices affect the specification; coefficients and the separating boundary are learned from the fit.", "links": [{"label": "StatQuest SVM video", "url": "https://youtu.be/efR1C6CvhmE"}, {"label": "ISLR classification resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-005", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "objective": "boundary-equality-convention", "stem": "How is a case exactly on a classifier boundary assigned?", "answer": "Use the stated inequality and label convention; equality handling must be specified.", "explanation": "", "links": []}, {"id": "C-006", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "objective": "new-case-fitted-scaler", "stem": "Why must new cases use the training scaler?", "answer": "The fitted model expects the same coordinate system; independent recentering or rescaling changes input meaning.", "explanation": "Use training means and scales. Centering each new observation by itself can erase its differences from other cases.", "links": [{"label": "scikit-learn preprocessing reference", "url": "https://scikit-learn.org/stable/modules/preprocessing.html"}]}, {"id": "R-051", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "Why is training accuracy an optimistic estimate of future performance?", "answer": "The model was fitted to those same observations.", "explanation": "", "links": [], "objective": "why-is-training-accuracy-an-optimistic-estimate-of-future-performance"}, {"id": "R-052", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What is overfitting?", "answer": "Fitting sample-specific noise that does not generalize.", "explanation": "", "links": [], "objective": "what-is-overfitting"}, {"id": "R-053", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What is underfitting?", "answer": "A model is too restrictive to capture useful structure.", "explanation": "", "links": [], "objective": "what-is-underfitting"}, {"id": "R-054", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What is the training set's role?", "answer": "Fit the model and learned preprocessing.", "explanation": "", "links": [], "objective": "what-is-the-training-set-s-role"}, {"id": "R-055", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What is the validation set's role?", "answer": "Choose among candidate models and settings.", "explanation": "", "links": [], "objective": "what-is-the-validation-set-s-role"}, {"id": "R-056", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What is the test set's role?", "answer": "Evaluate the selected procedure independently.", "explanation": "", "links": [], "objective": "what-is-the-test-set-s-role"}, {"id": "R-057", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "Why can the best validation score be too favorable?", "answer": "Selecting the winner can also select favorable validation noise.", "explanation": "A winner chosen among many candidates can benefit from sampling luck. A separate final test remains important.", "links": [{"label": "StatQuest cross-validation video", "url": "https://youtu.be/fSytzGwwBVw"}, {"label": "ISLR resampling resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "why-can-the-best-validation-score-be-too-favorable"}, {"id": "R-058", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "When can a simple train/test split suffice?", "answer": "When evaluating one predetermined procedure without using the test set for selection.", "explanation": "", "links": [], "objective": "when-can-a-simple-train-test-split-suffice"}, {"id": "R-060", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What is systematic rotation splitting?", "answer": "Assign records to sets using a repeating rule.", "explanation": "", "links": [], "objective": "what-is-systematic-rotation-splitting"}, {"id": "R-061", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "How can systematic splitting fail for periodically ordered data?", "answer": "The repeating split rule can align with the data cycle and isolate particular phases.", "explanation": "", "links": [], "objective": "how-can-systematic-splitting-fail-for-periodically-ordered-data"}, {"id": "R-062", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What is stratified splitting?", "answer": "Split within relevant groups to preserve representation.", "explanation": "", "links": [], "objective": "what-is-stratified-splitting"}, {"id": "R-063", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "How does k-fold cross-validation work?", "answer": "Rotate validation across k folds while fitting on the other k-1 folds.", "explanation": "", "links": [], "objective": "how-does-k-fold-cross-validation-work"}, {"id": "R-064", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "How often is a case used in k-fold CV?", "answer": "Validation once; training k-1 times.", "explanation": "", "links": [], "objective": "how-often-is-a-case-used-in-k-fold-cv"}, {"id": "R-065", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What should be refit after CV selects a specification?", "answer": "The chosen specification, using all non-test observations.", "explanation": "", "links": [], "objective": "what-should-be-refit-after-cv-selects-a-specification"}, {"id": "R-066", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "Why not simply average fold coefficients after selecting a model?", "answer": "Cross-validation selects a specification, not a default coefficient-averaging estimator.", "explanation": "", "links": [], "objective": "why-not-simply-average-fold-coefficients-after-selecting-a-model"}, {"id": "R-067", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What must happen to preprocessing inside CV?", "answer": "Fit learned preprocessing on each training fold and apply it to its validation fold.", "explanation": "Training-fold means, scales, loadings, and selected features should be applied to that fold's validation cases without learning from their outcomes.", "links": [{"label": "StatQuest cross-validation video", "url": "https://youtu.be/fSytzGwwBVw"}, {"label": "ISLR resampling resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "what-must-happen-to-preprocessing-inside-cv"}, {"id": "R-068", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What is data leakage?", "answer": "Using information that should be unavailable during training or decision-making.", "explanation": "Information can leak through timing, preprocessing, or selection. Adding trees does not repair unavailable inputs or an invalid evaluation.", "links": [{"label": "StatQuest cross-validation video", "url": "https://youtu.be/fSytzGwwBVw"}, {"label": "ISLR resampling resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "what-is-data-leakage"}, {"id": "R-069", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "Why use chronological validation for forecasts?", "answer": "Future information should not enter a model predicting from the past.", "explanation": "", "links": [], "objective": "why-use-chronological-validation-for-forecasts"}, {"id": "R-070", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "When should evaluation separate entire entities rather than individual rows?", "answer": "When deployment targets unseen entities and related rows share entity-specific information.", "explanation": "", "links": [], "objective": "when-should-evaluation-separate-entire-entities-rather-than-individual-rows"}, {"id": "R-071", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What is missing when a relevant deployment subgroup is absent from validation?", "answer": "A subgroup absent from validation cannot provide reliable evidence for that subgroup's deployment.", "explanation": "", "links": [], "objective": "what-is-missing-when-a-relevant-deployment-subgroup-is-absent-from-validation"}, {"id": "R-072", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "Why is no split fraction universally best?", "answer": "Sample size, representativeness, and the intended use differ.", "explanation": "", "links": [], "objective": "why-is-no-split-fraction-universally-best"}, {"id": "R-073", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "Why must the validation metric match the intended decision?", "answer": "The best statistical score need not give the best decision value.", "explanation": "", "links": [], "objective": "why-must-the-validation-metric-match-the-intended-decision"}, {"id": "R-074", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "Why does a final test estimate still have uncertainty?", "answer": "A finite test sample varies and may not represent every deployment condition.", "explanation": "", "links": [], "objective": "why-does-a-final-test-estimate-still-have-uncertainty"}, {"id": "C-007", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "objective": "fixed-versus-learned-conversion", "stem": "How does a fixed known unit conversion differ from learned preprocessing?", "answer": "A known conversion estimates nothing from held-out data; learned means, scales, loadings, or selections must respect training boundaries.", "explanation": "A deterministic conversion can still affect geometry if applied to only one feature. Absence of leakage does not imply identical model behavior.", "links": [{"label": "StatQuest cross-validation video", "url": "https://youtu.be/fSytzGwwBVw"}, {"label": "ISLR resampling resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-008", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "objective": "unequal-fold-aggregation", "stem": "How does pooled validation error differ from equally averaged fold error?", "answer": "Pooling weights each case equally; an equal-fold average weights each fold equally.", "explanation": "They match for equal fold sizes, but may differ substantially when fold sizes differ. Report which summary answers the evaluation question.", "links": [{"label": "StatQuest cross-validation video", "url": "https://youtu.be/fSytzGwwBVw"}, {"label": "ISLR resampling resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-009", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "objective": "comparable-performance-evidence", "stem": "What makes two model performance scores meaningfully comparable?", "answer": "Comparable representative evaluation cases and the same relevant error or decision metric.", "explanation": "A cleaner evaluation set or a differently scaled metric can confound the apparent model difference.", "links": [{"label": "StatQuest cross-validation video", "url": "https://youtu.be/fSytzGwwBVw"}, {"label": "ISLR resampling resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-010", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "objective": "underfit-overfit-diagnostic-contrast", "stem": "What error pattern suggests underfitting versus overfitting?", "answer": "Underfitting: poor training and validation fit. Overfitting: strong training fit but weak validation fit.", "explanation": "These are diagnostic patterns, not proof of a single cause. Representation, leakage, and population differences also need investigation.", "links": [{"label": "StatQuest cross-validation video", "url": "https://youtu.be/fSytzGwwBVw"}, {"label": "ISLR resampling resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "R-075", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What does clustering discover?", "answer": "Groups of observations similar under the chosen representation.", "explanation": "", "links": [], "objective": "what-does-clustering-discover"}, {"id": "R-076", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What is Euclidean/L2 distance?", "answer": "Straight-line distance: square root of summed squared coordinate differences.", "explanation": "", "links": [], "objective": "what-is-euclidean-l2-distance"}, {"id": "R-077", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What is Manhattan/L1 distance?", "answer": "Sum of absolute coordinate differences.", "explanation": "", "links": [], "objective": "what-is-manhattan-l1-distance"}, {"id": "R-078", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What is infinity-norm distance?", "answer": "The largest absolute coordinate difference.", "explanation": "", "links": [], "objective": "what-is-infinity-norm-distance"}, {"id": "R-079", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What is Minkowski distance of order p?", "answer": "(Sum of absolute coordinate differences raised to p) raised to 1/p.", "explanation": "", "links": [], "objective": "what-is-minkowski-distance-of-order-p"}, {"id": "R-080", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What makes feature weighting meaningful in distance calculations?", "answer": "Weights must represent relevant similarity rather than arbitrary units.", "explanation": "", "links": [], "objective": "what-makes-feature-weighting-meaningful-in-distance-calculations"}, {"id": "R-081", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What are the four basic steps of k-means?", "answer": "Initialize centers; assign to nearest centers; update means; repeat.", "explanation": "", "links": [], "objective": "what-are-the-four-basic-steps-of-k-means"}, {"id": "R-082", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What objective does standard Euclidean k-means minimize?", "answer": "Within-cluster sum of squared distances to the centers.", "explanation": "", "links": [], "objective": "what-objective-does-standard-euclidean-k-means-minimize"}, {"id": "R-083", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "Why distinguish squared distances from unsquared distances in k-means?", "answer": "The mean minimizes the squared-distance objective, not every possible distance objective.", "explanation": "", "links": [], "objective": "why-distinguish-squared-distances-from-unsquared-distances-in-k-means"}, {"id": "R-084", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What is a centroid?", "answer": "The mean coordinates of a cluster's assigned observations.", "explanation": "", "links": [], "objective": "what-is-a-centroid"}, {"id": "R-085", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "Why is k-means a heuristic?", "answer": "Different initial centers can lead to different local solutions.", "explanation": "", "links": [], "objective": "why-is-k-means-a-heuristic"}, {"id": "R-086", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What does repeated initialization accomplish in k-means?", "answer": "It helps find a better solution at the same k.", "explanation": "", "links": [], "objective": "what-does-repeated-initialization-accomplish-in-k-means"}, {"id": "R-087", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "Why should WSS not increase within a standard exact k-means iteration?", "answer": "Each assignment or mean update minimizes its part of the same objective.", "explanation": "", "links": [], "objective": "why-should-wss-not-increase-within-a-standard-exact-k-means-iteration"}, {"id": "R-088", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "Why does selecting k by minimum raw WSS alone fail?", "answer": "More clusters reduce WSS, even when the groups are not useful.", "explanation": "", "links": [], "objective": "why-does-selecting-k-by-minimum-raw-wss-alone-fail"}, {"id": "R-089", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What is the elbow method?", "answer": "Look for where added clusters give much smaller improvements.", "explanation": "", "links": [], "objective": "what-is-the-elbow-method", "diagram": "elbow"}, {"id": "R-090", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "Why can observed WSS from different heuristic runs fail to decrease monotonically with k?", "answer": "Different runs can stop at different local solutions.", "explanation": "", "links": [], "objective": "why-can-observed-wss-from-different-heuristic-runs-fail-to-decrease-monotonically-with-k"}, {"id": "R-091", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "How does k-means assign a new point?", "answer": "Assign it to the nearest learned center.", "explanation": "", "links": [], "objective": "how-does-k-means-assign-a-new-point"}, {"id": "R-092", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What is a Voronoi diagram?", "answer": "Regions whose points are closest to each respective center.", "explanation": "", "links": [], "objective": "what-is-a-voronoi-diagram"}, {"id": "R-093", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "Why is a distant nearest-center assignment not proof of a typical member?", "answer": "Nearest does not necessarily mean close enough or typical.", "explanation": "A remote point is still assigned to its closest center; the rule does not establish acceptable operational distance.", "links": [{"label": "StatQuest k-means video", "url": "https://youtu.be/4b5d3muPQmA"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "why-is-a-distant-nearest-center-assignment-not-proof-of-a-typical-member"}, {"id": "R-094", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "How do outliers affect k-means?", "answer": "They can pull the mean centers.", "explanation": "", "links": [], "objective": "how-do-outliers-affect-k-means"}, {"id": "R-095", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "When can separate clusterings by operating context be useful?", "answer": "When relevant similarity patterns differ across contexts that support separate decisions.", "explanation": "", "links": [], "objective": "when-can-separate-clusterings-by-operating-context-be-useful", "diagram": "clusters"}, {"id": "R-096", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "How can a facility budget affect k?", "answer": "It limits the number of feasible facilities or service groups.", "explanation": "", "links": [], "objective": "how-can-a-facility-budget-affect-k"}, {"id": "R-097", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "Why might direct geographic distance misrepresent travel?", "answer": "Roads, barriers, and travel constraints can change actual access time.", "explanation": "", "links": [], "objective": "why-might-direct-geographic-distance-misrepresent-travel"}, {"id": "R-098", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "Does changing cluster label names change the solution?", "answer": "No. Memberships, centers, and WSS are unchanged.", "explanation": "", "links": [], "objective": "does-changing-cluster-label-names-change-the-solution"}, {"id": "R-099", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "How do k in k-means,k-NN,and k-fold CV differ?", "answer": "Clusters, neighbors, and validation folds, respectively.", "explanation": "", "links": [], "objective": "how-do-k-in-k-means-k-nn-and-k-fold-cv-differ"}, {"id": "C-011", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "objective": "kmeans-required-inputs", "stem": "What data and choices define an ordinary k-means fit?", "answer": "Feature observations, a meaningful prepared geometry, the number of centers k, and an initialization policy.", "explanation": "Response labels are not required. Distances and center updates must match the stated squared-Euclidean objective.", "links": [{"label": "StatQuest k-means video", "url": "https://youtu.be/4b5d3muPQmA"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-012", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "objective": "norm-operational-choice", "stem": "When do L1 and infinity-norm distances match an operational task?", "answer": "L1 adds sequential requirements; infinity norm uses the longest simultaneous requirement.", "explanation": "Choose units that represent the task, such as per-axis travel times. Euclidean distance matches unrestricted straight-line distance, not every movement rule.", "links": [{"label": "StatQuest k-means video", "url": "https://youtu.be/4b5d3muPQmA"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-013", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "objective": "implicit-row-weight", "stem": "How do duplicate rows affect standard k-means?", "answer": "They contribute repeatedly to the objective and can pull centers toward that location.", "explanation": "Repeated rows may represent event frequency or accidental duplication. Clarify whether the observation unit is distinct entities or repeated demand.", "links": [{"label": "StatQuest k-means video", "url": "https://youtu.be/4b5d3muPQmA"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-014", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "objective": "uniform-coordinate-scaling", "stem": "What happens when every Euclidean coordinate is multiplied by the same positive factor a?", "answer": "Relative distances and equivalent memberships are preserved; WSS scales by a squared.", "explanation": "Correspondingly scale initial centers and keep tie handling equivalent. Changing one feature scale is different: it changes relative geometry.", "links": [{"label": "StatQuest k-means video", "url": "https://youtu.be/4b5d3muPQmA"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-015", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "objective": "case-weight-versus-feature-weight", "stem": "How do observation weights differ from feature weights in clustering?", "answer": "Observation weights emphasize cases; feature weights define which coordinate differences count more.", "explanation": "A visit count weights demand frequency. A coordinate weight changes similarity. Neither is automatically a fitted causal coefficient.", "links": [{"label": "StatQuest k-means video", "url": "https://youtu.be/4b5d3muPQmA"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-016", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "objective": "empty-cluster-mean", "stem": "Why does an empty k-means cluster need an explicit handling rule?", "answer": "No assigned observations means its ordinary mean is undefined.", "explanation": "An implementation must define what happens. There is no universal mean of an empty set; alternative clustering algorithms are not required here.", "links": [{"label": "StatQuest k-means video", "url": "https://youtu.be/4b5d3muPQmA"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-017", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "objective": "wss-comparability", "stem": "Why should WSS comparisons hold the data and geometry fixed?", "answer": "Changing rows, units, or feature weights changes the objective scale and the problem being measured.", "explanation": "", "links": []}, {"id": "R-100", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "What is a point outlier?", "answer": "An individually unusual observation.", "explanation": "", "links": [], "objective": "what-is-a-point-outlier"}, {"id": "R-101", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "What is a contextual outlier?", "answer": "An observation unusual for its time, place, or other context.", "explanation": "", "links": [], "objective": "what-is-a-contextual-outlier"}, {"id": "R-102", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "What is a collective outlier?", "answer": "An unusual group or sequence, even if individual values look normal.", "explanation": "", "links": [], "objective": "what-is-a-collective-outlier"}, {"id": "R-103", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "How can representation turn a collective anomaly into a point anomaly?", "answer": "Represent event gaps as intervals; an unusual missing event can become one extreme gap.", "explanation": "", "links": [], "objective": "how-can-representation-turn-a-collective-anomaly-into-a-point-anomaly"}, {"id": "R-104", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "What does an outlier flag from a boxplot establish?", "answer": "The value is unusual under that rule, not necessarily incorrect or suitable for deletion.", "explanation": "Flagging conventions vary. A rule for unusualness is not an automatic rule for excluding a record.", "links": [{"label": "ISLR linear-model diagnostics and unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "what-does-an-outlier-flag-from-a-boxplot-establish"}, {"id": "R-106", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "Why can model residuals help find contextual anomalies?", "answer": "They expose deviations from the expected response for a case's context.", "explanation": "", "links": [], "objective": "why-can-model-residuals-help-find-contextual-anomalies"}, {"id": "R-107", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "What should be investigated before excluding an outlier?", "answer": "Its validity, origin, and relevance to the intended population.", "explanation": "Distinguish an invalid record from a real rare event or another operating regime. Deletion solely to improve fit can hide relevant risk.", "links": [{"label": "ISLR linear-model diagnostics and unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "what-should-be-investigated-before-excluding-an-outlier"}, {"id": "R-108", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "What distinguishes a real rare event from a data error?", "answer": "A rare event is genuine; a data error misrepresents what happened.", "explanation": "", "links": [], "objective": "what-distinguishes-a-real-rare-event-from-a-data-error"}, {"id": "R-109", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "Why can deleting genuine tail events harm risk modeling?", "answer": "Rare but real events may dominate the losses the model is intended to assess.", "explanation": "", "links": [], "objective": "why-can-deleting-genuine-tail-events-harm-risk-modeling"}, {"id": "R-110", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "How can separate models handle ordinary and rare-event behavior?", "answer": "Separate regimes can preserve different behavior instead of forcing one common model.", "explanation": "", "links": [], "objective": "how-can-separate-models-handle-ordinary-and-rare-event-behavior"}, {"id": "R-111", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "When can excluding a valid unusual event be justified?", "answer": "When it is outside the clearly defined target population and the restriction is disclosed.", "explanation": "", "links": [], "objective": "when-can-excluding-a-valid-unusual-event-be-justified"}, {"id": "R-112", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "Does a better fitted score after deleting an outlier prove that the record was invalid?", "answer": "An improved fit is not proof that a flagged record is invalid.", "explanation": "", "links": [], "objective": "does-a-better-fitted-score-after-deleting-an-outlier-prove-that-the-record-was-invalid"}, {"id": "R-114", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "Why do large datasets naturally contain some extreme normal observations?", "answer": "Extreme but genuine values become more likely as the number of observations grows.", "explanation": "", "links": [], "objective": "why-do-large-datasets-naturally-contain-some-extreme-normal-observations"}, {"id": "C-018", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "objective": "joint-anomaly", "stem": "Can ordinary individual feature values form an unusual combination?", "answer": "Yes. Their joint or conditional relationship can be unusual even when each value looks ordinary.", "explanation": "", "links": []}, {"id": "C-019", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "objective": "residual-flag-missing-context", "stem": "Why can repeated residual outlier flags indicate a baseline problem?", "answer": "Missing systematic context can make normal cases repeatedly deviate from the modeled expectation.", "explanation": "Inspect omitted regimes or structure before interpreting every flagged case as corrupted.", "links": [{"label": "ISLR linear-model diagnostics and unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-020", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "objective": "missing-code-not-measurement", "stem": "How should a known numeric missing-value code be interpreted?", "answer": "As missing information, not as an actual extreme measurement.", "explanation": "A placeholder used as a real coordinate can distort means, distances, and anomaly detection. The handling policy needs to be explicit.", "links": [{"label": "ISLR linear-model diagnostics and unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "R-115", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "What does CUSUM mean and target?", "answer": "Cumulative sum; it detects sustained changes relative to a baseline.", "explanation": "", "links": [], "objective": "what-does-cusum-mean-and-target"}, {"id": "R-116", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "What is the upper CUSUM update?", "answer": "S_new=max(0,S_previous+x-mu-C).", "explanation": "", "links": [], "objective": "what-is-the-upper-cusum-update"}, {"id": "R-117", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "What is a positive-valued lower CUSUM update?", "answer": "S_new=max(0,S_previous+mu-x-C).", "explanation": "", "links": [], "objective": "what-is-a-positive-valued-lower-cusum-update"}, {"id": "R-118", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "How can both upward and downward changes be monitored?", "answer": "Use separate upper- and lower-direction monitors.", "explanation": "", "links": [], "objective": "how-can-both-upward-and-downward-changes-be-monitored"}, {"id": "R-119", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "What does CUSUM's baseline mu represent?", "answer": "The expected level under the reference process.", "explanation": "", "links": [], "objective": "what-does-cusum-s-baseline-mu-represent"}, {"id": "R-120", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "What does CUSUM's allowance C do?", "answer": "It reduces the contribution of each deviation to accumulated evidence.", "explanation": "", "links": [], "objective": "what-does-cusum-s-allowance-c-do"}, {"id": "R-121", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "What does CUSUM's threshold T do?", "answer": "It sets the accumulated evidence needed for an alarm.", "explanation": "", "links": [], "objective": "what-does-cusum-s-threshold-t-do"}, {"id": "R-122", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "Why does upper CUSUM reset negative raw totals to zero?", "answer": "To discard accumulated evidence in the opposite direction.", "explanation": "", "links": [], "objective": "why-does-upper-cusum-reset-negative-raw-totals-to-zero"}, {"id": "R-123", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "How does CUSUM use persistent directional deviations?", "answer": "Net directional deviations accumulate, potentially revealing changes that individual readings do not flag.", "explanation": "", "links": [], "objective": "how-does-cusum-use-persistent-directional-deviations"}, {"id": "R-124", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "Can a single extreme observation trigger CUSUM?", "answer": "Yes, if its contribution makes the statistic cross the threshold.", "explanation": "", "links": [], "objective": "can-a-single-extreme-observation-trigger-cusum"}, {"id": "R-125", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "What costs guide CUSUM tuning?", "answer": "False-alarm consequences and delayed or missed detection.", "explanation": "", "links": [], "objective": "what-costs-guide-cusum-tuning"}, {"id": "R-126", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "What is a CUSUM control chart?", "answer": "A plot of the accumulated statistic against its alarm threshold over the index.", "explanation": "", "links": [], "objective": "what-is-a-cusum-control-chart"}, {"id": "R-128", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "What makes change-detection reporting defensible?", "answer": "Disclose definitions and settings, and report supported conclusions instead of choosing a preferred result.", "explanation": "", "links": [], "objective": "what-makes-change-detection-reporting-defensible"}, {"id": "R-129", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "Why does a later end date alone not establish a longer period?", "answer": "Duration depends on both start and end; either boundary may change.", "explanation": "", "links": [], "objective": "why-does-a-later-end-date-alone-not-establish-a-longer-period"}, {"id": "C-021", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "objective": "allowance-blocks-departure", "stem": "Can a sustained above-baseline shift fail to accumulate in upper CUSUM?", "answer": "Yes. If the departure is smaller than the allowance, net increments may stay nonpositive.", "explanation": "Persistence alone does not guarantee detection with every chosen allowance. Use the stated update and the departure size of interest.", "links": [{"label": "NIST CUSUM explanation", "url": "https://www.itl.nist.gov/div898/handbook/pmc/section3/pmc323.htm"}]}, {"id": "C-022", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "objective": "negative-increment-versus-reset", "stem": "Does one below-baseline reading necessarily reset an upper CUSUM?", "answer": "No. A negative increment reduces the total; reset occurs only when the raw updated total is nonpositive.", "explanation": "", "links": []}, {"id": "C-023", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "objective": "statistic-versus-shift-size", "stem": "Why is a CUSUM statistic not the estimated mean-shift magnitude?", "answer": "It accumulates successive net deviations, rather than directly estimating a single level change.", "explanation": "", "links": []}, {"id": "C-024", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "objective": "reference-regime-suitability", "stem": "Why must a change monitor's reference match the intended operating regime?", "answer": "Normal differences between regimes can appear as departures from an inappropriate reference.", "explanation": "A monitor for occupied operation should not interpret expected occupancy effects as equipment deterioration merely because its reference came from empty operation.", "links": [{"label": "NIST CUSUM explanation", "url": "https://www.itl.nist.gov/div898/handbook/pmc/section3/pmc323.htm"}]}, {"id": "C-025", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "objective": "cusum-sequence-order", "stem": "Why does observation order matter to reset-to-zero CUSUM?", "answer": "Accumulation and resets depend on the sequential path, so shuffling can change alarm timing.", "explanation": "", "links": []}, {"id": "C-026", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "objective": "cusum-unit-consistency", "stem": "What must stay compatible when changing a CUSUM measurement scale?", "answer": "Transform the reference and scale the allowance and threshold consistently with response differences.", "explanation": "For a positive affine unit conversion, the common offset cancels in deviations; the positive scale factor changes accumulated evidence.", "links": [{"label": "NIST CUSUM explanation", "url": "https://www.itl.nist.gov/div898/handbook/pmc/section3/pmc323.htm"}]}, {"id": "R-130", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What are the components considered in exponential smoothing?", "answer": "Level, trend, and seasonality, depending on the specification.", "explanation": "", "links": [], "objective": "what-are-the-components-considered-in-exponential-smoothing"}, {"id": "R-131", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is the single exponential-smoothing update?", "answer": "S_t=alpha*x_t+(1-alpha)*S_(t-1).", "explanation": "", "links": [], "objective": "what-is-the-single-exponential-smoothing-update"}, {"id": "R-132", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "How does alpha control smoothing?", "answer": "Larger alpha gives more weight to the newest observation.", "explanation": "", "links": [], "objective": "how-does-alpha-control-smoothing"}, {"id": "R-133", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What happens at alpha=1 and alpha=0?", "answer": "Alpha=1 uses the latest observation; alpha=0 retains the initial level.", "explanation": "", "links": [], "objective": "what-happens-at-alpha-1-and-alpha-0"}, {"id": "R-134", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "Why is smoothing called exponential?", "answer": "Older observations receive exponentially declining weights.", "explanation": "", "links": [], "objective": "why-is-smoothing-called-exponential"}, {"id": "R-136", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is the single-smoothing h-step point forecast?", "answer": "The latest level at every ordinary point-forecast horizon.", "explanation": "", "links": [], "objective": "what-is-the-single-smoothing-h-step-point-forecast"}, {"id": "R-137", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is a simple starting level for exponential smoothing?", "answer": "The first observed response value.", "explanation": "This is one initialization choice; the starting level can also be estimated from the data.", "links": [{"label": "Forecasting textbook: single smoothing", "url": "https://otexts.com/fpp3/ses.html"}], "objective": "what-is-a-simple-starting-level-for-exponential-smoothing"}, {"id": "R-138", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is Holt's level update?", "answer": "S_t=alpha*x_t+(1-alpha)*(S_(t-1)+T_(t-1)).", "explanation": "", "links": [], "objective": "what-is-holt-s-level-update"}, {"id": "R-139", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is Holt's trend update?", "answer": "T_t=beta*(S_t-S_(t-1))+(1-beta)*T_(t-1).", "explanation": "", "links": [], "objective": "what-is-holt-s-trend-update"}, {"id": "R-140", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is Holt's h-step forecast?", "answer": "Current level+h*current trend.", "explanation": "", "links": [], "objective": "what-is-holt-s-h-step-forecast"}, {"id": "R-141", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What does initializing a smoothing trend to zero mean?", "answer": "The model starts with no assumed upward or downward change.", "explanation": "Zero is a simple starting choice, not a requirement. A trend can instead be estimated from early observations or fitted.", "links": [{"label": "Forecasting textbook: seasonal smoothing", "url": "https://otexts.com/fpp3/holt-winters.html"}], "objective": "what-does-initializing-a-smoothing-trend-to-zero-mean"}, {"id": "R-142", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What does seasonal cycle length L mean?", "answer": "The number of observations in one repeating cycle.", "explanation": "", "links": [], "objective": "what-does-seasonal-cycle-length-l-mean"}, {"id": "R-143", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "How is a calendar cycle converted into a seasonal observation count?", "answer": "Divide cycle duration by the observation interval when observations are regularly spaced.", "explanation": "One observation per item makes the cycle an item count. Calendar production duration is not the period for an item-indexed series.", "links": [{"label": "Forecasting textbook: seasonal smoothing", "url": "https://otexts.com/fpp3/holt-winters.html"}], "objective": "how-is-a-calendar-cycle-converted-into-a-seasonal-observation-count"}, {"id": "R-145", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What do multiplicative seasonal factors below, equal to, or above one mean?", "answer": "Below one reduces the baseline; one is neutral; above one increases it.", "explanation": "Interpret the response first: lower time until failure is worse reliability, but lower waste is less waste. A seasonal pattern does not establish a cause.", "links": [{"label": "Forecasting textbook: seasonal smoothing", "url": "https://otexts.com/fpp3/holt-winters.html"}], "objective": "what-do-multiplicative-seasonal-factors-below-equal-to-or-above-one-mean"}, {"id": "R-147", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "How do additive and multiplicative seasonal effects differ?", "answer": "Additive effects are amounts; multiplicative effects are ratios.", "explanation": "", "links": [], "objective": "how-do-additive-and-multiplicative-seasonal-effects-differ"}, {"id": "R-148", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is the multiplicative Holt-Winters level update?", "answer": "S_t=alpha*(x_t/C_(t-L))+(1-alpha)*(S_(t-1)+T_(t-1)).", "explanation": "", "links": [], "objective": "what-is-the-multiplicative-holt-winters-level-update"}, {"id": "R-149", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is the multiplicative Holt-Winters seasonal update?", "answer": "C_t=gamma*(x_t/S_t)+(1-gamma)*C_(t-L).", "explanation": "", "links": [], "objective": "what-is-the-multiplicative-holt-winters-seasonal-update"}, {"id": "R-150", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "Why does the seasonal update use t-L instead of t-1?", "answer": "It refers to the previous estimate for the same seasonal phase.", "explanation": "", "links": [], "objective": "why-does-the-seasonal-update-use-t-l-instead-of-t-1"}, {"id": "R-151", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is a neutral starting multiplicative seasonal factor?", "answer": "One: it leaves the baseline unchanged.", "explanation": "Neutral initialization assumes no seasonal effect initially; seasonal factors can instead be estimated from observed cycles.", "links": [{"label": "Forecasting textbook: seasonal smoothing", "url": "https://otexts.com/fpp3/holt-winters.html"}], "objective": "what-is-a-neutral-starting-multiplicative-seasonal-factor"}, {"id": "R-152", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is the one-step multiplicative Holt-Winters forecast?", "answer": "(Current level+current trend)*next phase's seasonal factor.", "explanation": "", "links": [], "objective": "what-is-the-one-step-multiplicative-holt-winters-forecast"}, {"id": "R-153", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "Why are zeros or negative values troublesome for multiplicative seasonality?", "answer": "Division and relative-scale effects can become unsuitable or undefined.", "explanation": "", "links": [], "objective": "why-are-zeros-or-negative-values-troublesome-for-multiplicative-seasonality"}, {"id": "R-154", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "How can smoothing coefficients be selected?", "answer": "Fit them to historical data, then check forecast performance on held-out future observations.", "explanation": "A good in-sample fit does not guarantee useful forecasts. Preserve time order when evaluating.", "links": [{"label": "Forecasting textbook: single smoothing", "url": "https://otexts.com/fpp3/ses.html"}], "objective": "how-can-smoothing-coefficients-be-selected"}, {"id": "R-155", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "Why distinguish a smoothed estimate from an advance forecast?", "answer": "A smoothed estimate can use the observation being estimated; an advance forecast cannot.", "explanation": "", "links": [], "objective": "why-distinguish-a-smoothed-estimate-from-an-advance-forecast"}, {"id": "R-156", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What do ARIMA's letters stand for?", "answer": "Autoregressive Integrated Moving Average.", "explanation": "", "links": [], "objective": "what-do-arima-s-letters-stand-for"}, {"id": "R-157", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What do p,d,q mean in ARIMA?", "answer": "Value lags, differencing order, and error lags, respectively.", "explanation": "", "links": [], "objective": "what-do-p-d-q-mean-in-arima"}, {"id": "R-158", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is a first difference?", "answer": "x_t-x_(t-1).", "explanation": "", "links": [], "objective": "what-is-a-first-difference"}, {"id": "R-159", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is a second difference?", "answer": "The difference between consecutive first differences.", "explanation": "", "links": [], "objective": "what-is-a-second-difference"}, {"id": "R-160", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What does ARIMA autoregression use as predictors?", "answer": "Earlier values of the modeled series.", "explanation": "", "links": [], "objective": "what-does-arima-autoregression-use-as-predictors"}, {"id": "R-161", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What does the ARIMA moving-average component use?", "answer": "Earlier prediction errors, not a rolling average of response observations.", "explanation": "", "links": [], "objective": "what-does-the-arima-moving-average-component-use"}, {"id": "R-162", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What does stationarity mean for a time series?", "answer": "Its statistical behavior, including mean and variability, remains stable over time.", "explanation": "Differencing can make some series more stable, but no single differencing choice is guaranteed to work for all data.", "links": [{"label": "Forecasting textbook: ARIMA", "url": "https://otexts.com/fpp3/non-seasonal-arima.html"}, {"label": "Forecasting textbook: stationarity and differencing", "url": "https://otexts.com/fpp3/stationarity.html"}], "objective": "what-does-stationarity-mean-for-a-time-series"}, {"id": "R-163", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is ARIMA(0,0,0) without a constant?", "answer": "White noise: no value lags, differencing, or error lags.", "explanation": "With a constant, it describes fluctuations around a fixed mean rather than necessarily around zero.", "links": [{"label": "Forecasting textbook: ARIMA", "url": "https://otexts.com/fpp3/non-seasonal-arima.html"}, {"label": "Forecasting textbook: stationarity and differencing", "url": "https://otexts.com/fpp3/stationarity.html"}], "objective": "what-is-arima-0-0-0-without-a-constant"}, {"id": "R-164", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is ARIMA(0,1,0) without drift?", "answer": "A random walk: the next value equals the previous value plus a random error.", "explanation": "First differences are white noise. Adding drift introduces a systematic average change.", "links": [{"label": "Forecasting textbook: ARIMA", "url": "https://otexts.com/fpp3/non-seasonal-arima.html"}, {"label": "Forecasting textbook: stationarity and differencing", "url": "https://otexts.com/fpp3/stationarity.html"}], "objective": "what-is-arima-0-1-0-without-drift"}, {"id": "R-165", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What are pure AR(p) and MA(q) specifications?", "answer": "ARIMA(p,0,0) and ARIMA(0,0,q), respectively.", "explanation": "", "links": [], "objective": "what-are-pure-ar-p-and-ma-q-specifications"}, {"id": "R-166", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "How is simple exponential smoothing related to ARIMA(0,1,1)?", "answer": "ARIMA(0,1,1) without a constant can produce equivalent simple exponential-smoothing forecasts.", "explanation": "The equivalence requires compatible parameterization and initialization; an arbitrary ARIMA(0,1,1) fit need not match an arbitrary smoothing fit.", "links": [{"label": "Forecasting: smoothing and ARIMA", "url": "https://otexts.com/fpp3/arima-ets.html"}], "objective": "how-is-simple-exponential-smoothing-related-to-arima-0-1-1"}, {"id": "R-167", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "Why does ARIMA need sufficient historical data?", "answer": "To estimate lag relationships and assess forecast reliability; more complex models generally need more observations.", "explanation": "There is no universal observation count that guarantees adequate fitting. Data quality, model complexity, and temporal coverage matter.", "links": [{"label": "Forecasting textbook: ARIMA", "url": "https://otexts.com/fpp3/non-seasonal-arima.html"}, {"label": "Forecasting textbook: stationarity and differencing", "url": "https://otexts.com/fpp3/stationarity.html"}], "objective": "why-does-arima-need-sufficient-historical-data"}, {"id": "R-168", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What does GARCH stand for?", "answer": "Generalized Autoregressive Conditional Heteroscedasticity.", "explanation": "", "links": [], "objective": "what-does-garch-stand-for"}, {"id": "R-169", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "How does GARCH's target differ from ARIMA's?", "answer": "GARCH forecasts variance; ARIMA forecasts response values.", "explanation": "", "links": [], "objective": "how-does-garch-s-target-differ-from-arima-s"}, {"id": "R-170", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What earlier quantities inform GARCH's variance estimate?", "answer": "Prior variance and squared prediction errors.", "explanation": "", "links": [], "objective": "what-earlier-quantities-inform-garch-s-variance-estimate"}, {"id": "R-171", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "Why does basic GARCH have no ARIMA-style differencing order d?", "answer": "It models conditional variance using past variances and squared errors, rather than differencing the response.", "explanation": "ARIMA differencing addresses the response level; GARCH describes changing conditional variance. These are different modeling tasks.", "links": [{"label": "arch project: mean and volatility model components", "url": "https://arch.readthedocs.io/en/latest/univariate/introduction.html"}], "objective": "why-does-basic-garch-have-no-arima-style-differencing-order-d"}, {"id": "R-172", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "Why is variance useful for planning?", "answer": "It helps plan for uncertainty, variability, and risk.", "explanation": "", "links": [], "objective": "why-is-variance-useful-for-planning"}, {"id": "C-027", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "objective": "smoothing-component-weights", "stem": "How do alpha, beta, and gamma differ in Holt-Winters?", "answer": "Alpha weights the level update; beta weights the trend update; gamma weights the seasonal update.", "explanation": "The components interact through the recursions, but the three settings have different direct roles.", "links": [{"label": "Forecasting textbook: seasonal smoothing", "url": "https://otexts.com/fpp3/holt-winters.html"}]}, {"id": "C-028", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "objective": "deseasonalized-level-update", "stem": "Why divide by the seasonal factor in a multiplicative level update?", "answer": "To remove that phase's proportional seasonal effect before updating the nonseasonal level.", "explanation": "", "links": []}, {"id": "C-029", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "objective": "differenced-forecast-restoration", "stem": "How is a one-step level forecast recovered from a predicted first difference?", "answer": "Add the predicted difference to the latest observed level.", "explanation": "The difference is an increment, not the next response value. Twice-differenced models require the corresponding additional reconstruction.", "links": [{"label": "Forecasting textbook: ARIMA", "url": "https://otexts.com/fpp3/non-seasonal-arima.html"}, {"label": "Forecasting textbook: stationarity and differencing", "url": "https://otexts.com/fpp3/stationarity.html"}]}, {"id": "C-030", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "objective": "garch-error-sign", "stem": "Why do equal positive and negative errors contribute equally to a GARCH squared-error term?", "answer": "Squaring removes the sign; their fluctuation magnitudes are equal.", "explanation": "", "links": []}, {"id": "C-031", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "objective": "variance-response-units", "stem": "What units does a variance forecast use?", "answer": "Squared response units; it is not itself a forecast of the response level.", "explanation": "", "links": []}, {"id": "C-032", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "objective": "smoothing-versus-lag-model", "stem": "How do smoothing and ARIMA represent temporal structure differently?", "answer": "Smoothing updates level, trend, and seasonal components; ARIMA uses value/error lags and possible differencing.", "explanation": "Different representations are candidates to evaluate. Greater generality or more parameters does not establish better forecasts.", "links": [{"label": "Forecasting textbook: ARIMA", "url": "https://otexts.com/fpp3/non-seasonal-arima.html"}, {"label": "Forecasting textbook: stationarity and differencing", "url": "https://otexts.com/fpp3/stationarity.html"}]}, {"id": "R-173", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What does ordinary linear regression estimate?", "answer": "A numeric response as a function of predictors.", "explanation": "", "links": [], "objective": "what-does-ordinary-linear-regression-estimate"}, {"id": "R-174", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What does linear in coefficients mean?", "answer": "The fitted coefficients enter linearly; transformed predictors can still produce curves.", "explanation": "", "links": [], "objective": "what-does-linear-in-coefficients-mean"}, {"id": "R-175", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What objective does ordinary least squares minimize?", "answer": "Sum of squared residuals.", "explanation": "", "links": [], "objective": "what-objective-does-ordinary-least-squares-minimize"}, {"id": "R-176", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "Why square regression residuals?", "answer": "It prevents positive and negative errors from cancelling and penalizes larger errors more.", "explanation": "", "links": [], "objective": "why-square-regression-residuals"}, {"id": "R-177", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "How is a regression coefficient interpreted without an interaction?", "answer": "The fitted response change for a one-unit predictor increase, holding other included predictors fixed.", "explanation": "In a model with an interaction, the slope also depends on the interacting predictor. In beta1*x1 + beta3*x1*x2, the x1 slope is beta1 + beta3*x2.", "links": [{"label": "ISLR linear-regression resources", "url": "https://www.statlearning.com/online-courses"}, {"label": "StatQuest video catalog: multiple regression", "url": "https://statquest.org/video_index.html"}], "objective": "how-is-a-regression-coefficient-interpreted-without-an-interaction"}, {"id": "R-178", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What does the intercept represent?", "answer": "The fitted response when the included predictors are zero.", "explanation": "", "links": [], "objective": "what-does-the-intercept-represent"}, {"id": "R-179", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "How does an interaction change an effect?", "answer": "The effect of one predictor can depend on another predictor's value.", "explanation": "", "links": [], "objective": "how-does-an-interaction-change-an-effect"}, {"id": "R-180", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What does a binary indicator coefficient compare?", "answer": "The fitted difference between the indicated group and its reference group, holding other predictors fixed.", "explanation": "", "links": [], "objective": "what-does-a-binary-indicator-coefficient-compare"}, {"id": "R-181", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "Why transform predictor columns?", "answer": "To represent relationships the original raw columns do not capture well.", "explanation": "", "links": [], "objective": "why-transform-predictor-columns"}, {"id": "R-182", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "Why does transforming the response require interpretation care?", "answer": "The output and coefficients now use a different response scale.", "explanation": "A coefficient or prediction on a transformed-response scale cannot automatically be labeled as a raw-unit change.", "links": [{"label": "ISLR linear-regression resources", "url": "https://www.statlearning.com/online-courses"}, {"label": "StatQuest video catalog: multiple regression", "url": "https://statquest.org/video_index.html"}], "objective": "why-does-transforming-the-response-require-interpretation-care"}, {"id": "R-183", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What is a regression residual?", "answer": "Observed response minus fitted response.", "explanation": "The ordinary regression residual is a response difference at the observed predictors, not the perpendicular geometric distance to the fitted line.", "links": [{"label": "ISLR linear-regression resources", "url": "https://www.statlearning.com/online-courses"}, {"label": "StatQuest video catalog: multiple regression", "url": "https://statquest.org/video_index.html"}], "objective": "what-is-a-regression-residual"}, {"id": "R-184", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What does a funnel-shaped residual plot suggest?", "answer": "Changing error spread across fitted values.", "explanation": "", "links": [], "objective": "what-does-a-funnel-shaped-residual-plot-suggest"}, {"id": "R-185", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What do long residual runs over time suggest?", "answer": "Possible temporal dependence or missing time structure.", "explanation": "", "links": [], "objective": "what-do-long-residual-runs-over-time-suggest"}, {"id": "R-186", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What does residual curvature suggest?", "answer": "A missing nonlinear relationship or unsuitable functional form.", "explanation": "", "links": [], "objective": "what-does-residual-curvature-suggest"}, {"id": "R-187", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "Why can strongly correlated predictors complicate separate coefficient interpretation?", "answer": "Their overlapping information can make separate coefficient interpretations difficult.", "explanation": "", "links": [], "objective": "why-can-strongly-correlated-predictors-complicate-separate-coefficient-interpretation"}, {"id": "R-188", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "Why can marginal and multiple-regression coefficient signs differ?", "answer": "Conditioning on other predictors can change the apparent relationship.", "explanation": "", "links": [], "objective": "why-can-marginal-and-multiple-regression-coefficient-signs-differ"}, {"id": "R-189", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What is likelihood?", "answer": "How compatible the observed data are with specified model parameters and assumptions.", "explanation": "", "links": [], "objective": "what-is-likelihood"}, {"id": "R-190", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "When does Gaussian maximum likelihood match least squares?", "answer": "Under independent, identically distributed normal errors.", "explanation": "", "links": [], "objective": "when-does-gaussian-maximum-likelihood-match-least-squares"}, {"id": "R-191", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "How does AIC combine likelihood and model size?", "answer": "AIC = -2*log-likelihood + 2*K; lower comparable scores are preferred.", "explanation": "K counts fitted parameters under a consistent convention. Higher likelihood can be outweighed by the penalty for extra parameters.", "links": [{"label": "ISLR model-selection resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "how-does-aic-combine-likelihood-and-model-size"}, {"id": "R-192", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What is AICc?", "answer": "AIC with a finite-sample correction.", "explanation": "", "links": [], "objective": "what-is-aicc"}, {"id": "R-193", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "How does BIC combine likelihood and model size?", "answer": "BIC = -2*log-likelihood + K*log(n); lower comparable scores are preferred.", "explanation": "The extra-parameter penalty is log(n), compared with 2 in AIC. For sufficiently large n, BIC penalizes an extra parameter more strongly.", "links": [{"label": "ISLR model-selection resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "how-does-bic-combine-likelihood-and-model-size"}, {"id": "R-194", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What is relative AIC support for a model Delta above the best?", "answer": "exp(-Delta/2), as a relative comparison rather than proof of truth.", "explanation": "", "links": [], "objective": "what-is-relative-aic-support-for-a-model-delta-above-the-best"}, {"id": "R-195", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What must be consistent when comparing information criteria?", "answer": "Response, observations, likelihood convention, and parameter counting.", "explanation": "", "links": [], "objective": "what-must-be-consistent-when-comparing-information-criteria"}, {"id": "R-196", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What is a coefficient standard error?", "answer": "Estimated sampling uncertainty in a fitted coefficient.", "explanation": "", "links": [], "objective": "what-is-a-coefficient-standard-error"}, {"id": "R-197", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What is the coefficient t-statistic for a specified null value?", "answer": "(Estimated coefficient - null value)/standard error; for a zero null, coefficient/standard error.", "explanation": "", "links": [], "objective": "what-is-the-coefficient-t-statistic-for-a-specified-null-value"}, {"id": "R-198", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What does a p-value mean?", "answer": "Under the null and assumptions, the probability of a result at least as extreme as observed.", "explanation": "A p-value is not the probability that the coefficient or null hypothesis is true, and it does not measure practical importance.", "links": [{"label": "StatQuest p-value video", "url": "https://youtu.be/vemZtEM63GY"}, {"label": "ISLR regression-inference resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "what-does-a-p-value-mean"}, {"id": "R-199", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "Why is a significant coefficient not necessarily important?", "answer": "Statistical evidence does not establish a large or valuable effect.", "explanation": "", "links": [], "objective": "why-is-a-significant-coefficient-not-necessarily-important"}, {"id": "R-200", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What does a confidence interval including zero imply for a matching two-sided test?", "answer": "No rejection of zero at the matching level, not proof of no relationship.", "explanation": "", "links": [], "objective": "what-does-a-confidence-interval-including-zero-imply-for-a-matching-two-sided-test"}, {"id": "R-201", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What is ordinary R-squared?", "answer": "1-SSE/SST: fitted response variation explained relative to the mean baseline.", "explanation": "", "links": [], "objective": "what-is-ordinary-r-squared"}, {"id": "R-202", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "Why can adding predictors increase R-squared without improving prediction?", "answer": "Additional flexibility can fit training noise.", "explanation": "", "links": [], "objective": "why-can-adding-predictors-increase-r-squared-without-improving-prediction"}, {"id": "R-203", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What is adjusted R-squared?", "answer": "R-squared adjusted for model size; it can fall when predictors are added.", "explanation": "", "links": [], "objective": "what-is-adjusted-r-squared"}, {"id": "R-204", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "Why can held-out R-squared be negative?", "answer": "Its squared error can exceed the evaluation mean-response baseline's error.", "explanation": "", "links": [], "objective": "why-can-held-out-r-squared-be-negative"}, {"id": "R-205", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "Why do predictive associations and change signals not establish causality?", "answer": "They can reflect shared causes, reverse relationships, or selection; they do not identify intervention effects.", "explanation": "This limit applies to classifiers, regressions, seasonal patterns, importance scores, and change alarms. Accurate prediction or significant association does not alone identify why.", "links": [{"label": "StatQuest p-value video", "url": "https://youtu.be/vemZtEM63GY"}, {"label": "ISLR regression-inference resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "why-do-predictive-associations-and-change-signals-not-establish-causality"}, {"id": "C-033", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "objective": "intercept-range-caution", "stem": "Why can a regression intercept lack a useful operational interpretation?", "answer": "The zero-predictor condition may be outside the observed or meaningful range.", "explanation": "The intercept remains part of the equation. An unhelpful extrapolated zero-case does not alone invalidate every in-range prediction.", "links": [{"label": "ISLR linear-regression resources", "url": "https://www.statlearning.com/online-courses"}, {"label": "StatQuest video catalog: multiple regression", "url": "https://statquest.org/video_index.html"}]}, {"id": "C-034", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "objective": "error-scale-conversion", "stem": "How do residuals and SSE change under a common response-unit factor a?", "answer": "Residuals scale by a; SSE scales by a squared.", "explanation": "Raw errors with different response units are not directly comparable evidence of model quality.", "links": [{"label": "ISLR linear-regression resources", "url": "https://www.statlearning.com/online-courses"}, {"label": "StatQuest video catalog: multiple regression", "url": "https://statquest.org/video_index.html"}]}, {"id": "R-206", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What family of response transformations does Box-Cox provide?", "answer": "Power transformations of positive responses, with logarithms as the zero-power case.", "explanation": "", "links": [], "objective": "what-family-of-response-transformations-does-box-cox-provide"}, {"id": "R-208", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What can Box-Cox try to improve?", "answer": "Response shape and model behavior, including error-spread patterns; improvement is not guaranteed.", "explanation": "", "links": [], "objective": "what-can-box-cox-try-to-improve"}, {"id": "R-209", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "Does ordinary regression require a normal raw-response histogram?", "answer": "No. The relevant normal-error assumptions concern errors, not just the raw histogram.", "explanation": "A normal-looking response or predictor histogram does not prove the relevant model assumptions.", "links": [{"label": "StatQuest PCA video", "url": "https://youtu.be/FgakZw6K1QQ"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "does-ordinary-regression-require-a-normal-raw-response-histogram"}, {"id": "R-210", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What is heteroscedasticity?", "answer": "Nonconstant error variance.", "explanation": "", "links": [], "objective": "what-is-heteroscedasticity"}, {"id": "R-211", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What is detrending?", "answer": "Remove an estimated or known systematic temporal baseline.", "explanation": "", "links": [], "objective": "what-is-detrending"}, {"id": "R-212", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "How does detrending differ from differencing?", "answer": "Detrending removes a baseline function; differencing subtracts neighboring observations.", "explanation": "", "links": [], "objective": "how-does-detrending-differ-from-differencing"}, {"id": "R-213", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "How do you recover original-scale predictions after subtractive detrending?", "answer": "Add the fitted trend back to the predicted remaining component.", "explanation": "", "links": [], "objective": "how-do-you-recover-original-scale-predictions-after-subtractive-detrending"}, {"id": "R-214", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What does ordinary PCA do, and what information defines its directions?", "answer": "It creates orthogonal directions ranked by prepared predictor variance, without using response labels.", "explanation": "", "links": [], "objective": "what-does-ordinary-pca-do-and-what-information-defines-its-directions"}, {"id": "R-215", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "Why center data before ordinary PCA?", "answer": "To measure variation around feature means; scaling also matters when units differ.", "explanation": "", "links": [], "objective": "why-center-data-before-ordinary-pca"}, {"id": "R-216", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What matrix gives ordinary PCA loading directions?", "answer": "The prepared predictors' covariance/correlation matrix or equivalent centered cross-product matrix.", "explanation": "", "links": [], "objective": "what-matrix-gives-ordinary-pca-loading-directions"}, {"id": "R-217", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What is a principal component loading?", "answer": "An original feature's weight in a component direction.", "explanation": "", "links": [], "objective": "what-is-a-principal-component-loading"}, {"id": "R-218", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What is a principal component score?", "answer": "An observation's value after projection onto a component direction.", "explanation": "", "links": [], "objective": "what-is-a-principal-component-score"}, {"id": "R-219", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What is an eigenvector/eigenvalue relationship?", "answer": "A*v=lambda*v: the direction is preserved while its magnitude is scaled.", "explanation": "", "links": [], "objective": "what-is-an-eigenvector-eigenvalue-relationship"}, {"id": "R-220", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What fraction of X variance does a component explain?", "answer": "Its eigenvalue divided by the total eigenvalues.", "explanation": "", "links": [], "objective": "what-fraction-of-x-variance-does-a-component-explain"}, {"id": "R-221", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "Why can retaining all PCA directions preserve information?", "answer": "A complete coordinate change retains all dimensions.", "explanation": "", "links": [], "objective": "why-can-retaining-all-pca-directions-preserve-information"}, {"id": "R-222", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "Why does ordinary PCA not guarantee better response prediction?", "answer": "PCA uses predictor variance, not the response, to choose directions.", "explanation": "A low-variance component can contain information about the response. Evaluate the whole predictive pipeline.", "links": [{"label": "StatQuest PCA video", "url": "https://youtu.be/FgakZw6K1QQ"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "why-does-ordinary-pca-not-guarantee-better-response-prediction"}, {"id": "R-224", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What is feature extraction versus feature selection?", "answer": "Extraction creates combinations; selection keeps original variables.", "explanation": "", "links": [], "objective": "what-is-feature-extraction-versus-feature-selection"}, {"id": "R-225", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "How are component-regression coefficients mapped back?", "answer": "Combine the fitted component slopes with the corresponding loadings.", "explanation": "", "links": [], "objective": "how-are-component-regression-coefficients-mapped-back"}, {"id": "R-226", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What raw-unit correction follows regression on standardized PCA scores?", "answer": "Undo training scaling and centering before interpreting original-unit slopes and the intercept.", "explanation": "", "links": [], "objective": "what-raw-unit-correction-follows-regression-on-standardized-pca-scores"}, {"id": "R-227", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "Why do strongly correlated standardized predictors often yield one dominant PC?", "answer": "Shared movement concentrates predictor variance in one direction.", "explanation": "", "links": [], "objective": "why-do-strongly-correlated-standardized-predictors-often-yield-one-dominant-pc", "diagram": "pca"}, {"id": "R-228", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What should guide choosing how many PCA components to retain for prediction?", "answer": "Predictor-variance retention and downstream validation, not a guaranteed response-accuracy percentage.", "explanation": "", "links": [], "objective": "what-should-guide-choosing-how-many-pca-components-to-retain-for-prediction"}, {"id": "R-229", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "Why must test PCA use the training loadings?", "answer": "New cases must use the same coordinate system as the fitted model.", "explanation": "Reuse the fitted training means, scales, and loadings; a new coordinate system changes the downstream model's input meaning.", "links": [{"label": "StatQuest PCA video", "url": "https://youtu.be/FgakZw6K1QQ"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "why-must-test-pca-use-the-training-loadings"}, {"id": "C-035", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "objective": "pca-axis-sign", "stem": "Does reversing a PCA axis imply a different substantive component?", "answer": "No. Reversing its loadings and scores describes the same axis.", "explanation": "A component-regression prediction stays unchanged if its slope is also reversed; the score-times-slope product is preserved.", "links": [{"label": "StatQuest PCA video", "url": "https://youtu.be/FgakZw6K1QQ"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-036", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "objective": "equal-eigenvalue-interpretation", "stem": "What do equal PCA eigenvalues imply about variance importance?", "answer": "Those directions have equal predictor variance; the ranking alone does not favor one.", "explanation": "Equal variance does not prove duplicated raw features, equal response effects, or a particular causal interpretation.", "links": [{"label": "StatQuest PCA video", "url": "https://youtu.be/FgakZw6K1QQ"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-037", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "objective": "predictor-response-transform-contrast", "stem": "How does a predictor transformation differ from a response transformation?", "answer": "A predictor transformation changes inputs; a response transformation changes the output scale.", "explanation": "A transformed predictor can still predict the original response units. A transformed response needs appropriate interpretation and restoration.", "links": [{"label": "NIST Box-Cox explanation", "url": "https://www.itl.nist.gov/div898/handbook/pmc/section5/pmc52.htm"}, {"label": "ISLR regression resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "R-230", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does CART stand for?", "answer": "Classification and Regression Trees.", "explanation": "", "links": [], "objective": "what-does-cart-stand-for"}, {"id": "R-231", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does an ordinary regression leaf predict?", "answer": "The mean of the training responses in that leaf.", "explanation": "", "links": [], "objective": "what-does-an-ordinary-regression-leaf-predict"}, {"id": "R-232", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does a classification leaf predict?", "answer": "The most frequent class in that leaf.", "explanation": "", "links": [], "objective": "what-does-a-classification-leaf-predict"}, {"id": "R-233", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is a model tree compared with ordinary CART?", "answer": "It fits a richer local model in each leaf instead of only a constant response.", "explanation": "", "links": [], "objective": "what-is-a-model-tree-compared-with-ordinary-cart"}, {"id": "R-234", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What are root,internal node,and leaf?", "answer": "Root: start. Internal node: split. Leaf: terminal prediction.", "explanation": "", "links": [], "objective": "what-are-root-internal-node-and-leaf"}, {"id": "R-235", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is recursive binary splitting?", "answer": "Repeatedly split the current region using a feature and threshold.", "explanation": "", "links": [], "objective": "what-is-recursive-binary-splitting", "diagram": "tree"}, {"id": "R-236", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "Why compare child SSE or weighted variances in regression splits?", "answer": "Larger children contain more cases and contribute more to overall fit.", "explanation": "", "links": [], "objective": "why-compare-child-sse-or-weighted-variances-in-regression-splits"}, {"id": "R-237", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "Which controls limit tree growth and unsupported leaves?", "answer": "Minimum leaf size, required split improvement, depth limits, and pruning.", "explanation": "Apply the stated minimum to each proposed child, not the parent or average child size. Tiny leaves may fit idiosyncratic cases.", "links": [{"label": "ISLR tree-model resources", "url": "https://www.statlearning.com/online-courses"}, {"label": "StatQuest video catalog: classification and regression trees", "url": "https://statquest.org/video_index.html"}], "objective": "which-controls-limit-tree-growth-and-unsupported-leaves"}, {"id": "R-238", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does pruning do?", "answer": "Remove branches that do not improve evaluated performance.", "explanation": "", "links": [], "objective": "what-does-pruning-do"}, {"id": "R-239", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "How should a percentage-based minimum leaf-size guideline be interpreted?", "answer": "As a heuristic for limiting tiny leaves, not a universal optimal setting.", "explanation": "Choose a suitable minimum using the available data and validation performance; check every proposed child leaf.", "links": [{"label": "ISLR tree-model resources", "url": "https://www.statlearning.com/online-courses"}, {"label": "StatQuest video catalog: classification and regression trees", "url": "https://statquest.org/video_index.html"}], "objective": "how-should-a-percentage-based-minimum-leaf-size-guideline-be-interpreted"}, {"id": "R-240", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "How should the factor-model observations-per-factor guideline be interpreted?", "answer": "Roughly ten observations per selected factor is a heuristic, not guaranteed adequacy.", "explanation": "", "links": [], "objective": "how-should-the-factor-model-observations-per-factor-guideline-be-interpreted"}, {"id": "R-241", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "How does raising a tree's required split improvement usually affect growth?", "answer": "A larger required improvement usually permits fewer marginal splits.", "explanation": "", "links": [], "objective": "how-does-raising-a-tree-s-required-split-improvement-usually-affect-growth"}, {"id": "R-243", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "How does random predictor selection help a random forest?", "answer": "It diversifies trees by limiting the candidate predictors considered at each split.", "explanation": "Less similar trees can have errors that partly offset when their predictions are combined.", "links": [{"label": "StatQuest random-forest video", "url": "https://youtu.be/J4Wdy0Wc_xQ"}, {"label": "ISLR tree-model resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "how-does-random-predictor-selection-help-a-random-forest"}, {"id": "R-244", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "How does a forest aggregate predictions?", "answer": "Average numeric predictions; combine votes for class predictions.", "explanation": "", "links": [], "objective": "how-does-a-forest-aggregate-predictions"}, {"id": "R-245", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "When can combining trees reduce overreaction to training noise?", "answer": "When their mistakes differ enough to partly offset; shared mistakes can persist.", "explanation": "", "links": [], "objective": "when-can-combining-trees-reduce-overreaction-to-training-noise"}, {"id": "R-249", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "How should correct training classifications be combined across differently sized leaves?", "answer": "Add correct cases and total cases across leaves; do not average leaf percentages without their sizes.", "explanation": "", "links": [], "objective": "how-should-correct-training-classifications-be-combined-across-differently-sized-leaves"}, {"id": "R-250", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "Why is forest variable importance not a causal coefficient?", "answer": "Predictive contribution does not establish a signed, constant, causal effect.", "explanation": "Predictor importance can summarize contribution without providing a signed slope or evidence that changing that predictor causes a benefit.", "links": [{"label": "StatQuest random-forest video", "url": "https://youtu.be/J4Wdy0Wc_xQ"}, {"label": "ISLR tree-model resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "why-is-forest-variable-importance-not-a-causal-coefficient"}, {"id": "R-251", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is logistic regression's predicted probability?", "answer": "p=1/(1+exp(-eta)), where eta is the fitted linear predictor.", "explanation": "", "links": [], "objective": "what-is-logistic-regression-s-predicted-probability"}, {"id": "R-252", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What response data fit basic binary logistic regression?", "answer": "Known binary outcomes, coded 0/1, and suitable predictors.", "explanation": "", "links": [], "objective": "what-response-data-fit-basic-binary-logistic-regression"}, {"id": "R-253", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "Why can ordinary linear regression be unsuitable for predicting a binary-event probability?", "answer": "Its numeric predictions can fall outside zero to one.", "explanation": "", "links": [], "objective": "why-can-ordinary-linear-regression-be-unsuitable-for-predicting-a-binary-event-probability"}, {"id": "R-255", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "How is basic logistic regression normally fitted?", "answer": "Iterative likelihood-based fitting, not ordinary closed-form least squares.", "explanation": "", "links": [], "objective": "how-is-basic-logistic-regression-normally-fitted"}, {"id": "R-256", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does a logistic threshold do?", "answer": "It turns a probability estimate into a class or action.", "explanation": "", "links": [], "objective": "what-does-a-logistic-threshold-do"}, {"id": "R-257", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "Why is a threshold of .5 not automatically best?", "answer": "Different errors and actions can have different consequences.", "explanation": "", "links": [], "objective": "why-is-a-threshold-of-5-not-automatically-best"}, {"id": "R-258", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What happens when a fixed positive-score threshold increases?", "answer": "Fewer or the same positive predictions; misses can rise and false alarms can fall.", "explanation": "", "links": [], "objective": "what-happens-when-a-fixed-positive-score-threshold-increases"}, {"id": "R-259", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "Why is pseudo-R-squared different from ordinary R-squared?", "answer": "It is a differently defined fit summary; check the definition rather than assuming variance explained.", "explanation": "Software can define different pseudo-R-squared summaries. It is neither an individual event probability nor automatically an ordinary response-variance fraction.", "links": [{"label": "ISLR tree-model resources", "url": "https://www.statlearning.com/online-courses"}, {"label": "StatQuest video catalog: classification and regression trees", "url": "https://statquest.org/video_index.html"}], "objective": "why-is-pseudo-r-squared-different-from-ordinary-r-squared"}, {"id": "R-260", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is a true positive?", "answer": "Actually positive and predicted positive.", "explanation": "", "links": [], "objective": "what-is-a-true-positive"}, {"id": "R-261", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is a false positive?", "answer": "Actually negative but predicted positive.", "explanation": "", "links": [], "objective": "what-is-a-false-positive"}, {"id": "R-262", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is a true negative?", "answer": "Actually negative and predicted negative.", "explanation": "", "links": [], "objective": "what-is-a-true-negative"}, {"id": "R-263", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is a false negative?", "answer": "Actually positive but predicted negative.", "explanation": "", "links": [], "objective": "what-is-a-false-negative"}, {"id": "R-264", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is sensitivity or recall?", "answer": "TP/(TP+FN): the fraction of actual positives detected.", "explanation": "", "links": [], "objective": "what-is-sensitivity-or-recall"}, {"id": "R-265", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is specificity?", "answer": "TN/(TN+FP): the fraction of actual negatives correctly classified.", "explanation": "", "links": [], "objective": "what-is-specificity"}, {"id": "R-266", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is precision or positive predictive value?", "answer": "TP/(TP+FP): the fraction of positive predictions that are correct.", "explanation": "", "links": [], "objective": "what-is-precision-or-positive-predictive-value"}, {"id": "R-267", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is overall accuracy?", "answer": "(TP+TN)/N.", "explanation": "", "links": [], "objective": "what-is-overall-accuracy"}, {"id": "R-268", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is negative predictive value?", "answer": "TN/(TN+FN): the fraction of negative predictions that are correct.", "explanation": "", "links": [], "objective": "what-is-negative-predictive-value"}, {"id": "R-269", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is ROC's pair of axes?", "answer": "x: false-positive rate. y: sensitivity/true-positive rate.", "explanation": "", "links": [], "objective": "what-is-roc-s-pair-of-axes"}, {"id": "R-270", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does ROC AUC measure?", "answer": "How often a random positive scores above a random negative; a ranking measure.", "explanation": "", "links": [], "objective": "what-does-roc-auc-measure"}, {"id": "R-271", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does AUC=.5 mean?", "answer": "Chance-level positive-versus-negative ranking, not necessarily 50% classification accuracy.", "explanation": "", "links": [], "objective": "what-does-auc-5-mean"}, {"id": "R-272", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "How do prevalence changes affect evaluation?", "answer": "Precision, accuracy, and expected cost can change even if sensitivity and specificity stay fixed.", "explanation": "Class frequencies alter population performance even when the stated within-class rates remain fixed.", "links": [{"label": "StatQuest ROC video", "url": "https://youtu.be/4jRBRDbJemM"}, {"label": "StatQuest video catalog: confusion metrics", "url": "https://statquest.org/video_index.html"}], "objective": "how-do-prevalence-changes-affect-evaluation"}, {"id": "R-273", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "Which confusion cells can contribute to decision cost, and how is cost totaled?", "answer": "All four can carry cost: multiply each count by its cell cost and add.", "explanation": "Correct actions can consume resources too. Dividing total cost by the number of cases yields cost per case; the zero-correct-cost simplification must be stated.", "links": [{"label": "ISLR classification and decision-rule resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "which-confusion-cells-can-contribute-to-decision-cost-and-how-is-cost-totaled"}, {"id": "R-274", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is expected cost at positive prevalence pi?", "answer": "pi*[Se*cTP+(1-Se)*cFN]+(1-pi)*[(1-Sp)*cFP+Sp*cTN], assuming the conditional rates transfer.", "explanation": "", "links": [], "objective": "what-is-expected-cost-at-positive-prevalence-pi"}, {"id": "R-275", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is the cost-optimal positive threshold with calibrated p and correct decisions free?", "answer": "cFP/(cFP+cFN), when correct decisions cost zero and the stated probability/cost assumptions apply.", "explanation": "Compare the expected costs of each action. Additional action costs or constraints can change the policy.", "links": [{"label": "ISLR classification and decision-rule resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "what-is-the-cost-optimal-positive-threshold-with-calibrated-p-and-correct-decisions-free"}, {"id": "R-276", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does Poisson regression model?", "answer": "An expected count or arrival rate as a function of attributes.", "explanation": "", "links": [], "objective": "what-does-poisson-regression-model"}, {"id": "R-277", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What are regression splines and knots?", "answer": "Polynomial pieces joined smoothly at knots.", "explanation": "", "links": [], "objective": "what-are-regression-splines-and-knots"}, {"id": "R-278", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does MARS stand for?", "answer": "Multivariate Adaptive Regression Splines.", "explanation": "", "links": [], "objective": "what-does-mars-stand-for"}, {"id": "R-279", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does Bayesian regression combine?", "answer": "Prior information about unknown quantities with observed data.", "explanation": "Prior distributions express information about unknown quantities. They are not fabricated known response labels, and inappropriate strong priors can mislead.", "links": [{"label": "ISLR regression, nonlinear-model, and Bayesian companion resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "what-does-bayesian-regression-combine"}, {"id": "R-280", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is k-NN regression's defining output rule?", "answer": "Average the numeric responses of the k nearest training cases.", "explanation": "", "links": [], "objective": "what-is-k-nn-regression-s-defining-output-rule"}, {"id": "C-038", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "objective": "positive-class-reversal", "stem": "How do confusion cells change when the positive class is reversed?", "answer": "TP swaps with TN, and FP swaps with FN; accuracy stays unchanged.", "explanation": "Class-conditional metrics and predictive values can change because their named denominators change. Define the positive event before interpreting a table.", "links": [{"label": "StatQuest ROC video", "url": "https://youtu.be/4jRBRDbJemM"}, {"label": "StatQuest video catalog: confusion metrics", "url": "https://statquest.org/video_index.html"}]}, {"id": "C-039", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "objective": "threshold-gap", "stem": "Can changing a probability threshold leave every class decision unchanged?", "answer": "Yes. If no score crosses between the thresholds, the positive set stays the same.", "explanation": "", "links": []}, {"id": "C-040", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "objective": "ranking-versus-probability-values", "stem": "Why can models have equal AUC but different probability or threshold behavior?", "answer": "AUC depends on ranking; numerical probability values and fixed-threshold decisions can differ.", "explanation": "Identical ordering does not establish accurate probabilities or equal decisions at the same numeric threshold.", "links": [{"label": "StatQuest ROC video", "url": "https://youtu.be/4jRBRDbJemM"}, {"label": "StatQuest video catalog: confusion metrics", "url": "https://statquest.org/video_index.html"}]}, {"id": "C-041", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "objective": "prior-suitability", "stem": "Why should strong Bayesian prior information be scrutinized with little data?", "answer": "It can substantially influence updated estimates, especially when the observations provide limited evidence.", "explanation": "The prior and data are combined, not treated as equally reliable by definition. Examine whether the prior applies to the actual population.", "links": [{"label": "ISLR regression, nonlinear-model, and Bayesian companion resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-042", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "objective": "count-mean-versus-event-probability", "stem": "How does an expected count differ from a binary-event probability?", "answer": "A count mean can exceed one; an event probability lies between zero and one.", "explanation": "Poisson regression directly models an attribute-dependent count mean; binary logistic regression directly models the stated event probability.", "links": [{"label": "ISLR regression, nonlinear-model, and Bayesian companion resources", "url": "https://www.statlearning.com/online-courses"}]}]};
